package app.boardlens.companion;
import android.app.*;import android.widget.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.ShadowAlertDialog;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,application=Application.class)
public class MobileTimingTest {
 @Test public void quickTimeControlsSaveIndependentBudgetsAndMakeDepthTimerEffective(){PhoneScreenActivity activity=Robolectric.buildActivity(PhoneScreenActivity.class).setup().get();PhoneSettings prefs=new PhoneSettings(activity);prefs.p.edit().clear().putString("mode","Depth").apply();activity.showTiming();org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();AlertDialog dialog=ShadowAlertDialog.getLatestAlertDialog();EditText move=dialog.findViewById(android.R.id.content).findViewWithTag("move_seconds"),eval=dialog.findViewById(android.R.id.content).findViewWithTag("eval_seconds");assertNotNull(move);assertNotNull(eval);move.setText("0.12");eval.setText("0.08");dialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();assertEquals(.12f,prefs.seconds(),.001);assertEquals(.08f,prefs.evaluationSeconds(),.001);assertEquals("Time + depth",prefs.mode());activity.finish();}
 @Test public void invalidTimesStayOpenAndDoNotOverwriteSavedSettings(){PhoneScreenActivity activity=Robolectric.buildActivity(PhoneScreenActivity.class).setup().get();PhoneSettings prefs=new PhoneSettings(activity);prefs.p.edit().clear().putFloat("seconds",.5f).apply();activity.showTiming();org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();AlertDialog dialog=ShadowAlertDialog.getLatestAlertDialog();EditText move=dialog.findViewById(android.R.id.content).findViewWithTag("move_seconds");move.setText("NaN");dialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();assertTrue(dialog.isShowing());assertNotNull(move.getError());assertEquals(.5f,prefs.seconds(),.001);dialog.dismiss();activity.finish();}
 @Test public void evaluationCanBeDisabledAndStaysDisabledAcrossReopening(){PhoneScreenActivity a=Robolectric.buildActivity(PhoneScreenActivity.class).setup().get();PhoneSettings prefs=new PhoneSettings(a);prefs.p.edit().clear().putBoolean("evaluation_enabled",false).apply();a.finish();PhoneScreenActivity reopened=Robolectric.buildActivity(PhoneScreenActivity.class).setup().get();assertFalse(new PhoneSettings(reopened).evaluationEnabled());assertEquals(.2f,new PhoneSettings(reopened).evaluationSeconds(),.001);reopened.finish();}
}
